{
  "kind": "domain",
  "name": "ctxtrace",
  "body": {
    "problem": "AI と開発すると、できた実装 ・ テスト ・ 差分は残るが、そこへ至る判断（何を読み、どう解釈し、何を根拠にしたか）は残らない",
    "value": {
      "for": "AI と開発する人",
      "what": "AI が何を読み、どう解釈し、何を根拠にしたかを記録として残す",
      "why": "できた実装の隣に、そこへ至る判断を残すため",
      "distinct": "AI が見たと言った引用を、原文と文字列で照合する"
    },
    "stakeholders": [
      { "who": "AI と開発する人", "interest": "判断の過程を後から読める" },
      { "who": "記録を分析する人", "interest": "版の違う記録が混ざらない" },
      { "who": "接続先を使っている人", "interest": "記録のせいで操作が遅くならない" }
    ],
    "scope": {
      "in":  ["フックからの記録", "記録の正規化", "引用と原文の照合", "記録への問い合わせ"],
      "out": ["何を書かせるかの中身（設定から差し込む）", "外への送信"]
    },
    "success": [
      "対話1件ごとに、読んだ場所 ・ 解釈 ・ 根拠 ・ 探索の打ち切り ・ 人の介入の5つが残る",
      "AI が引いた引用ごとに、原文との照合の結果が残る"
    ],
    "quality": ["記録を外へ送らない", "フック1回の記録で、接続先を待たせない"],
    "subdomains": ["SD-記録する", "SD-照合する", "SD-問い合わせる"]
  }
}

{
  "kind": "implementation",
  "domain": "DM-ctxtrace",
  "repository": "ctxtrace",
  "root": ".",
  "stack": {
    "language": "rust",
    "tools": [
      "cargo",
      "clippy",
      "rustfmt"
    ]
  },
  "layers": [
    {
      "name": "domain",
      "where": [
        "crates.contract",
        "crates.source",
        "crates.core"
      ]
    },
    {
      "name": "application",
      "where": [
        "crates.app"
      ]
    },
    {
      "name": "adapter",
      "where": [
        "adapters.claude_code",
        "adapters.files",
        "adapters.sqlite",
        "crates.bundle"
      ]
    },
    {
      "name": "entry",
      "where": [
        "crates.cli",
        "crates.mcp"
      ]
    }
  ],
  "subdomains": [
    {
      "ref": "SD-記録する",
      "logic": "domain-model",
      "tests": "pyramid"
    },
    {
      "ref": "SD-照合する",
      "logic": "domain-model",
      "tests": "pyramid"
    },
    {
      "ref": "SD-問い合わせる",
      "logic": "transaction-script",
      "tests": "inverted-pyramid"
    }
  ],
  "rules": ".coding-rules/rules.json"
}
